package com.gamingevents.controller;
import com.gamingevents.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class RegistrationController { final RegistrationRepository registrations; final UserRepository users; final PlayerProfileRepository profiles; public RegistrationController(RegistrationRepository r,UserRepository u,PlayerProfileRepository p){registrations=r;users=u;profiles=p;} @GetMapping("/players/tournaments") @PreAuthorize("hasRole('PLAYER')") public List<Map<String,Object>> mine(Authentication a){var p=profiles.findByUserId(users.findByEmail(a.getName()).orElseThrow().getId()).orElseThrow();return registrations.findByPlayer(p).stream().map(r->Map.<String,Object>of("id",r.getTournament().getId(),"name",r.getTournament().getName(),"game",r.getTournament().getGameName(),"status",r.getTournament().getStatus().name())).toList();} @GetMapping("/tournaments/{id}/players") @PreAuthorize("hasAnyRole('ORGANIZER','ADMIN')") public List<Map<String,Object>> players(@PathVariable Long id){return registrations.findAll().stream().filter(r->r.getTournament().getId().equals(id)).map(r->Map.<String,Object>of("id",r.getPlayer().getId(),"username",r.getPlayer().getUsername())).toList();}}
